-- Seed do catálogo global de sintomas (v1). Idempotente: upsert por código.
-- ATENÇÃO: conteúdo técnico inicial — deve ser revisado por um mecânico experiente
-- antes de ir para uma oficina piloto (pesos, causas, verificações e tempos).

insert into public.symptom_categories (code, name, icon, description, sort_order) values
  ('freios', 'Freios', 'disc', 'Frenagem hidráulica, ABS, pastilhas, discos e acionamento.', 1),
  ('motor', 'Motor', 'engine', 'Combustão, ignição, alimentação e gerenciamento eletrônico.', 2),
  ('transmissao', 'Transmissão', 'gear', 'Câmbio manual ou automático, embreagem e semieixos.', 3),
  ('suspensao', 'Suspensão e Direção', 'spring', 'Amortecimento, geometria, articulações e direção.', 4),
  ('eletrica', 'Elétrica', 'bolt', 'Bateria, alternador, partida, painel e acessórios.', 5),
  ('arrefecimento', 'Arrefecimento', 'thermo', 'Radiador, bomba d''água, válvula termostática e ventoinha.', 6)
on conflict (code) do update set
  name = excluded.name, icon = excluded.icon, description = excluded.description, sort_order = excluded.sort_order;

