  "checks":[{"name":"Comparar temperatura lida e temperatura real","tools":["Scanner automotivo","Termômetro infravermelho"],"estimated_minutes":15},{"name":"Testar relés e comando da ventoinha","tools":["Multímetro"],"estimated_minutes":20}],
  "parts":[{"name":"Sensor de temperatura do motor","avg_quantity":1},{"name":"Relé da ventoinha","avg_quantity":1},{"name":"Válvula termostática","avg_quantity":1}]},
 {"cat":"arrefecimento","code":"cooling_no_heat","name":"Ar quente não esquenta","description":"Aquecimento interno fraco ou inexistente.","minutes":120,
  "questions":[{"id":"engine_temp","text":"O motor atinge a temperatura normal de trabalho?","type":"boolean"},{"id":"coolant","text":"O nível do reservatório está correto?","type":"select","options":["Sim","Não","Não verifiquei"]}],
  "causes":[{"name":"Válvula termostática travada aberta","weight":0.65,"notes":"Motor demora a aquecer."},{"name":"Ar no sistema de arrefecimento","weight":0.55,"notes":"Fazer sangria."},{"name":"Radiador de aquecimento obstruído","weight":0.45,"notes":"Mangueiras com temperaturas diferentes."},{"name":"Atuador da portinhola de ar com defeito","weight":0.35,"notes":"Mistura de ar não muda."}],
  "checks":[{"name":"Verificar temperatura de trabalho e mangueiras do aquecedor","tools":["Termômetro infravermelho"],"estimated_minutes":15},{"name":"Sangrar o sistema de arrefecimento","tools":["Funil de sangria"],"estimated_minutes":25}],
