$json$::jsonb) as x(cat text, code text, name text, description text, minutes int,
                    questions jsonb, causes jsonb, checks jsonb, parts jsonb)
), numbered as (
  select src.*, row_number() over () as rn from src
)
insert into public.symptoms
  (category_id, code, name, description, follow_up_questions, probable_causes, recommended_checks,
   typical_parts, avg_service_minutes, sort_order)
select c.id, n.code, n.name, n.description, n.questions, n.causes, n.checks, n.parts, n.minutes, n.rn
from numbered n
join public.symptom_categories c on c.code = n.cat
on conflict (code) do update set
  category_id = excluded.category_id, name = excluded.name, description = excluded.description,
  follow_up_questions = excluded.follow_up_questions, probable_causes = excluded.probable_causes,
  recommended_checks = excluded.recommended_checks, typical_parts = excluded.typical_parts,
  avg_service_minutes = excluded.avg_service_minutes, sort_order = excluded.sort_order;
